-- Migration: Album credits and cover art for each song.
-- album/year/cover_url come from the iTunes catalog, matched by hand to each
-- song's original album; year is the song's first release. cover_color is the
-- dominant colour of the cover, precomputed so the page can tint itself.

ALTER TABLE songs ADD COLUMN album TEXT NOT NULL DEFAULT '';
ALTER TABLE songs ADD COLUMN year INTEGER NOT NULL DEFAULT 0;
ALTER TABLE songs ADD COLUMN cover_url TEXT NOT NULL DEFAULT '';
ALTER TABLE songs ADD COLUMN cover_color TEXT NOT NULL DEFAULT '#000000';

